import 'dart:convert';
import 'dart:typed_data';

/// Small, bundled checkout illustrations supplied for GlowHit.
/// Keeping them in source avoids runtime network requests during checkout.
class CheckoutArtwork {
  CheckoutArtwork._();

  static final Uint8List fastDelivery = base64Decode(
    ''
  );

  static final Uint8List rupee = base64Decode(
    ''
  );

  static final Uint8List smartphone = base64Decode(
    ''
  );
}
